import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CS-cBh1g.js";const u=JSON.parse('{"title":"How changes get reviewed","description":"","frontmatter":{},"headers":[],"relativePath":"agents/review.md","filePath":"agents/review.md"}'),n={name:"agents/review.md"};function s(i,e,d,h,c,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="how-changes-get-reviewed" tabindex="-1">How changes get reviewed <a class="header-anchor" href="#how-changes-get-reviewed" aria-label="Permalink to &quot;How changes get reviewed&quot;">​</a></h1><p>You tell your agent what you want in its chat. You review what it did in Mayhem. There is no task queue to keep in sync with the conversation: the unit of review is a <strong>branch</strong>.</p><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Agent does</th><th>In the app</th></tr></thead><tbody><tr><td>1</td><td>Works on a branch (never <code>main</code>) and commits. Asks you in the chat when what you want is unclear.</td><td>The branch appears under <strong>Changes → To review</strong>.</td></tr><tr><td>2</td><td><code>behavior_diff</code> with <code>base: &quot;main&quot;</code>: what you&#39;ll be shown. Anything in it that it didn&#39;t mean to change, it fixes.</td><td>The branch&#39;s risk chip.</td></tr><tr><td>3</td><td><code>run_scenarios</code> with <code>base: &quot;main&quot;</code>, <code>after: &quot;HEAD&quot;</code>: every button, every auto and every team scenario, on the commit.</td><td><strong>sim proof passed</strong>, <strong>differs</strong> or <strong>failed</strong> on the branch.</td></tr><tr><td>4</td><td>Tells you it&#39;s ready.</td><td>You review it in <a href="/Mayhem/suite/changes">Changes</a>.</td></tr></tbody></table><p>The prompt under <strong>Settings → Agents and the project file → Tell your agent once</strong> says exactly this. Paste it into the chat, or into the robot repo&#39;s <code>CLAUDE.md</code> or <code>AGENTS.md</code> so every session starts with it. Agents using the Mayhem MCP server are told the same when they connect.</p><h2 id="code-simulate-read-fix" tabindex="-1">Code, simulate, read, fix <a class="header-anchor" href="#code-simulate-read-fix" aria-label="Permalink to &quot;Code, simulate, read, fix&quot;">​</a></h2><p>For a behavior bug, agents are expected to close the loop before asking you:</p><ol><li>Change the code, and regenerate <code>MayhemProject.h</code> with <code>tools/mayhem/export.sh</code> if the project or <code>machines.json</code> changed.</li><li>Run the relevant <a href="/Mayhem/robot-code/scenarios">sim proof scenarios</a> on the uncommitted code (<code>run_scenarios</code>).</li><li>Read the result&#39;s log: <code>log_states</code> for a state machine problem; <code>log_anomalies</code>, <code>log_what_changed</code> and <code>log_table</code> for anything else.</li><li>Fix and repeat. Before handing off, add a scenario that reproduces the bug, so it stays fixed, then commit and run everything on the commit (step 3 above).</li></ol><h2 id="the-sim-proof-is-recorded-not-described" tabindex="-1">The sim proof is recorded, not described <a class="header-anchor" href="#the-sim-proof-is-recorded-not-described" aria-label="Permalink to &quot;The sim proof is recorded, not described&quot;">​</a></h2><p>When <code>run_scenarios</code> runs on a commit, the tool writes the result onto that commit as a git note: how many scenarios ran, which failed, which behave differently, what it was compared with, who ran it and when. That record is what you see on the branch. An agent can&#39;t type it in, a run on uncommitted files isn&#39;t recorded, and a newer commit has none until a proof is run on it. If the agent didn&#39;t run one, the branch says <strong>no sim proof</strong>, and <strong>Run sim proof</strong> runs it and keeps the result.</p><p>Notes stay on the computer they were made on unless pushed (<code>git push origin refs/notes/mayhem-proof</code>). That&#39;s fine when the agent runs in your terminal, which is the usual setup.</p><h2 id="how-risky-a-change-is" tabindex="-1">How risky a change is <a class="header-anchor" href="#how-risky-a-change-is" aria-label="Permalink to &quot;How risky a change is&quot;">​</a></h2><p>Mayhem rates every branch with the same review the <a href="/Mayhem/suite/changes">Changes</a> page shows:</p><table tabindex="0"><thead><tr><th>Risk</th><th>Means</th></tr></thead><tbody><tr><td><strong>Red</strong></td><td>CAN IDs, current limits, brake/coast, motor directions, gear ratios, offsets; or generated code out of date</td></tr><tr><td><strong>Yellow</strong></td><td>Driver controls, state machines, other values, any other robot code, a removed or loosened scenario</td></tr><tr><td><strong>Green</strong></td><td>Only auto paths changed, and every changed path still finishes</td></tr><tr><td><strong>None</strong></td><td>Nothing that reaches the robot changed (notes, a new scenario)</td></tr></tbody></table><p>Most real fixes touch C++ logic that Mayhem can&#39;t read, so they&#39;re yellow. Judge those by the sim proof.</p><h2 id="after-you-merge" tabindex="-1">After you merge <a class="header-anchor" href="#after-you-merge" aria-label="Permalink to &quot;After you merge&quot;">​</a></h2><p>Merge the branch yourself (agents don&#39;t push to <code>main</code>). It moves to <strong>Merged</strong>, and Mayhem follows it without anyone reporting anything: <strong>in main</strong> however it got there (merge, rebase or squash), <strong>on the robot</strong> once the code read off the robot includes it, <strong>in a log</strong> once a collected log says it ran that code. Agents never deploy.</p>',17)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
